using Dip.Domain.Enums; using Dip.Domain.Exceptions; using Dip.Domain.ValueObjects; namespace Dip.Domain.Entities; public sealed class PipelineRun { private PipelineRun(){} public PipelineRun(Guid id,Guid projectId,CommitSha sha,string collectorType,string collectorVersion,DateTimeOffset queuedAtUtc){Id=id==Guid.Empty?Guid.NewGuid():id;ProjectId=projectId;CommitSha=sha;CollectorType=Req(collectorType,100);CollectorVersion=Req(collectorVersion,50);Status=PipelineStatus.Queued;QueuedAtUtc=queuedAtUtc;} public Guid Id{get;private set;} public Guid ProjectId{get;private set;} public CommitSha CommitSha{get;private set;} public string CollectorType{get;private set;}=string.Empty; public string CollectorVersion{get;private set;}=string.Empty; public PipelineStatus Status{get;private set;} public DateTimeOffset QueuedAtUtc{get;private set;} public DateTimeOffset? StartedAtUtc{get;private set;} public DateTimeOffset? FinishedAtUtc{get;private set;} public string? FailureReason{get;private set;} public void Start(DateTimeOffset at){Ensure(PipelineStatus.Queued);Status=PipelineStatus.Running;StartedAtUtc=at;} public void Complete(DateTimeOffset at){Ensure(PipelineStatus.Running);Status=PipelineStatus.Succeeded;FinishedAtUtc=at;} public void Fail(string reason,DateTimeOffset at){if(Status is not(PipelineStatus.Queued or PipelineStatus.Running)) throw new DomainException($"Cannot fail from {Status}.");FailureReason=Req(reason,2000);Status=PipelineStatus.Failed;FinishedAtUtc=at;} private void Ensure(PipelineStatus s){if(Status!=s) throw new DomainException($"Expected {s}, was {Status}.");} private static string Req(string v,int max){v=v?.Trim()??string.Empty;if(v.Length<1||v.Length>max) throw new ArgumentException("Invalid text value.");return v;} }